macro_rules! add_workspace_submodules {
    () => {
        pub fn add_workspace_submodules (root_dir : & Path , dry_run : bool , executor : Arc < dyn Execv + Send + Sync > ,) -> anyhow :: Result < () > { println ! ("Adding all submodules as path dependencies to [workspace.dependencies]...") ; let cargo_toml_path = root_dir . join ("Cargo.toml") ; let submodules_dir = root_dir . join ("submodules") ; let mut doc = fs :: read_to_string (& cargo_toml_path) ? . parse :: < toml_edit :: DocumentMut > () ? ; let workspace_deps = doc . get_mut ("workspace") . and_then (| item : & mut Item | item . as_table_mut ()) . and_then (| table : & mut Table | table . get_mut ("dependencies")) . and_then (| item : & mut Item | item . as_table_mut ()) . ok_or_else (| | anyhow :: anyhow ! ("Could not find [workspace.dependencies] in Cargo.toml")) ? ; let mut submodule_names : Vec < String > = fs :: read_dir (& submodules_dir) ? . filter_map (| entry | { let entry = entry . ok () ? ; if entry . file_type () . ok () ? . is_dir () { entry . file_name () . into_string () . ok () } else { None } }) . collect () ; submodule_names . sort () ; for submodule in submodule_names { let dep_path = format ! ("./submodules/{}" , submodule) ; let item = toml_edit :: Item :: Table (toml_edit :: Table :: new ()) ; let mut dep_table = item . into_table () . unwrap () ; dep_table . insert ("path" , toml_edit :: value (dep_path)) ; match submodule . as_str () { "serde" => { workspace_deps . insert ("serde" , toml_edit :: Item :: Table (dep_table . clone ())) ; workspace_deps . insert ("serde_derive" , toml_edit :: value (format ! ("{{ path = \"./submodules/serde/serde_derive\" }}")) ,) ; workspace_deps . insert ("serde_core" , toml_edit :: value (format ! ("{{ path = \"./submodules/serde/serde_core\" }}")) ,) ; } "time-rs" => { workspace_deps . insert ("time" , toml_edit :: Item :: Table (dep_table . clone ())) ; workspace_deps . insert ("time-core" , toml_edit :: value (format ! ("{{ path = \"./submodules/time-rs/time-core\" }}")) ,) ; workspace_deps . insert ("time-macros" , toml_edit :: value (format ! ("{{ path = \"./submodules/time-rs/time-macros\" }}")) ,) ; } "rand" => { workspace_deps . insert ("rand" , toml_edit :: Item :: Table (dep_table . clone ())) ; workspace_deps . insert ("rand08" , toml_edit :: value (format ! ("{{ path = \"./submodules/rand\" }}")) ,) ; workspace_deps . insert ("rand09" , toml_edit :: value (format ! ("{{ path = \"./submodules/rand\" }}")) ,) ; } _ => { workspace_deps . insert (& submodule , toml_edit :: Item :: Table (dep_table)) ; } } } if dry_run { println ! ("--- DRY RUN: Generated Cargo.toml content ---") ; println ! ("{}" , doc . to_string ()) ; println ! ("---------------------------------------------") ; } else { fs :: write (& cargo_toml_path , doc . to_string ()) ? ; println ! ("Successfully updated Cargo.toml with submodule workspace dependencies.") ; } Ok (()) }
    };
}

add_workspace_submodules!();